#include "KS/SRC/ks/FEMenu_shared.h"

class PauseMenuSystem : public FEMenuSystem
{
public:
    enum {
        PauseMenu, TimeAttackPauseMenu, TutorialPauseMenu, EndRunMenu,
        HeatMidMenu, HeatEndMenu, CompEndMenu, OptionsMenu, GoalsMenu,
        LostControllerMenu, SoundMenu, CameraMenu, TrickTypeMenu,
        PlaylistMenu, ReplayMenu, MapMenu, HighScoreMenu, PhotoMenu,
        TutorialMenu, SaveLoadMenu, SaveConfirmMenu, TipMenu,
        QuitConfirmMenu, NumMenus
    };

    virtual void MakeActive(int m, int sm);
};

void PauseMenuSystem::MakeActive(int m, int sm)
{
    if((m == OptionsMenu || m == ReplayMenu || m == TrickTypeMenu || m == GoalsMenu || m == TipMenu || m == QuitConfirmMenu) &&
       (active == PauseMenu || active == TimeAttackPauseMenu || active == TutorialPauseMenu || active == EndRunMenu || active == HeatMidMenu || active == HeatEndMenu || active == CompEndMenu))
        menus[m]->setBack(menus[active]);
    FEMenuSystem::MakeActive(m, sm);
}
